class Pair{ int row; int col; int dist; Pair(int row,int col,int dist) { this.row = row; this.col = col; this.dist = dist; } } class Solution { public int[][] updateMatrix(int[][] mat) { int rows = mat.length; int cols = mat[0].length; int[][] distance = new int[rows][cols]; Queue<Pair> q = new LinkedList<>(); boolean[][] b = new boolean[rows][cols]; for (int i = 0; i < rows; i++) { for (int j = 0; j < cols; j++) { if (mat[i][j] == 0) { q.add(new Pair(i,j,0)); b[i][j] = true; } } } while (!q.isEmpty()) { Pair p = q.poll(); distance[p.row][p.col] = p.dist; if (p.col + 1 < cols && !b[p.row][p.col + 1]) { b[p.row][p.col + 1] = true; q.add(new Pair(p.row,p.col + 1,p.dist + 1)); } if (p.col - 1 >= 0 && !b[p.row][p.col - 1]) { b[p.row][p.col - 1] = true; q.add(new Pair(p.row,p.col - 1,p.dist + 1)); } if (p.row + 1 < rows && !b[p.row + 1][p.col]) { b[p.row + 1][p.col] = true; q.add(new Pair(p.row + 1,p.col,p.dist + 1)); } if (p.row - 1 >= 0 && !b[p.row - 1][p.col]) { b[p.row - 1][p.col] = true; q.add(new Pair(p.row - 1,p.col,p.dist + 1)); } } return distance; } }